import math
def find_symmetry_centers(snowflake_points, k):
    x_coords, y_coords = zip(*snowflake_points)
    xsum, ysum = sum(x_coords), sum(y_coords)
    x_mean, y_mean = xsum / len(snowflake_points), ysum / len(snowflake_points)

    center_points = []
    for x, y in snowflake_points:
        if (x - x_mean) * (x - x_mean) + (y - y_mean) * (y - y_mean) <= k * k:
            center_points.append((math.sqrt(k) * (x - x_mean) + x_mean, math.sqrt(k) * (y - y_mean) + y_mean))

    if len(center_points):
        return len(center_points), " ".join(str(coord) for coord in center_points)
    else:
        return -1

