    for u in range(1, n + 1):
        visited = set()
        for v in range(1, n + 1):
            if u != v and visited ^ {u, v} == visited:
                # Check if the path leads to a cycle
                pathLength = 0
                toVisit = [u]
                while toVisit:
                    nextToVisit = set()
                    for vertex in toVisit:
                        nextToVisit |= graph[vertex].difference(visited)
                    toVisit = nextToVisit
                    if len(toVisit) == 0:
                        break
                    pathLength += 1
                    if pathLength >= 4:
                        break
                if len(toVisit) == 0:
                    # Found a cycle
                    simpleCycleEdges |= {u, v}
                    break

    return len(simpleCycleEdges), sorted(list(simpleCycleEdges))
