from math import comb
from functools import lru_cache

@lru_cache(maxsize=None)
def solve(n, k):
    if n == 1:
        return 0 if k == 1 else 1 if k == 0 else 0
    elif n % 2 == 0:
        if k < 0:
            return 0
        if k == 1:
            return comb(n-1, 1) * solve(n-1, k)
        else:
            return comb(2*k + 2*k*(k+1)//2, k) * (n-1) * solve(n-1, k-1)
    else:
        if k == 1 or k == 2:
            return 2
        elif k == n:
            return (k-1) * solve(n-1, k-1)
        else:
            return comb(k + k*(k-1)//2, k) * solve(n-2, k-2) + solve(n-2, k-1)

