from operator import add

MOD = 998244353

def solve(N):
    dp = [0] * (2*N+1)
    for i in range(1, 2*N+1):
        dp[i] = (dp[i-1] + i) % MOD

    @lru_cache(maxsize=None)
    def rec(start, end):
        if end <= start:
            return 0
        elif start == end-1:
            return dp[start]

        target = (start + end) // 2
        return dp[end] + dp[start] - dp[target-1] + sum(rec(a, i) for a, i in enumerate(range(start+1, end), end)) % MOD

    return rec(0, N)

