import math

def is_symmetrical(x1, y1, x2, y2):
    """
    Check if two points are symmetrical around a point (x_center, y_center).
    """
    x_center, y_center = x2, y2
    if x1 == x2:
        return y1 == y_center
    if y1 == y2:
        return x1 == x_center
    return False

def find_center_of_symmetry(n, k, coordinates):
    """
    Find all symmetry centers of the snowflake.
    """
    if n == 0 and k > 0:
        return 1, coordinates[0]
    size = n
    sym_centers = []

    while size:
        if k > 0 and size % 2 == 1:
            size -= 1
            continue

        for i in range(size // 2):
            if is_symmetrical(i, 0, n - i - size // 2 + 1, 0) and is_symmetrical(-size // 2 + i + 1, 0, 0, n - i - size // 2 + 1):
                sym_centers.append(f"{i} {0}")
                sym_centers.append(f"{size // 2 - i - 1} {0}")

        for i in range(size // 2, size):
            if is_symmetrical(i, 0, n - i - size // 2 + 1, 0):
                sym_centers.append(f"{(i - size // 2) * 2 + 1} {0}")
            if is_symmetrical(i, 0, i - size // 2 + 1, n - i - size // 2 + 1):
                sym_centers.append(f"{(i - size // 2) * 2} {0}")

        if k > 0:
            size //= 2
            k -= 1
        else:
            break

    if k > 0 or len(sym_centers) < 1:
        return -1

    return len(sym_centers), sym_centers

