def max_removed_spaceships(n, m, weapons):
    # Count the occurrences of each weapon type
    weapon_counts = [0] * 3
    for weapon in weapons:
        weapon_counts[weapon[0]] += 1

    # Create a bitmask to represent the state of the spaceships
    mask = [0] * m
    for i in range(m):
        # Initialize the bitmask for each spaceship
        for weapon in weapons:
            # Add the spaceship to the bitmask if it was hit by a certain type of weapon
            if weapon[0] == 0:
                if weapon[1] == 0:  # SQL rocket
                    mask[i] |= (1 << (i % 10))  # Odd target (0, 9, ...)
                elif weapon[1] == 1:  # Cognition beam
                    if i < m // 2:
                        mask[i] |= (1 << (i // 2))  # Even left side of the line
                    else:
                        mask[i] |= (1 << (i // 2 + m // 2))  # Even right side of the line
            elif weapon[0] == 2:
                # OMG bazooka
                for j in range(i, m):
                    if min(j % 10, m - j % 10) < 2:
                        mask[j] |= (1 << i)

    # Initialize the dp table
    dp = [[-1] * m for _ in range(1 << m)]
    dp[0][0] = 0

    # Extend the dp table
    for plane in range(1, (1 << m)):
        for j in range(m):
            if (plane & (1 << j)) == 0 or mask[j] & plane == mask[j]:
                dp[plane][j] = max(dp[plane][(1 << j) | mask[j]], dp[plane][j])
            else:
                dp[plane][j] = max(dp[plane][(1 << j) | mask[j]], dp[plane - (1 << j)][j])

    # Find the maximum number of removed spaceships
    max_removed_spaceships = -1
    for j in range(m):
        if mask[j] == (1 << m) - 1:
            max_removed_spaceships = max(max_removed_spaceships, j + 1)

    return max_removed_spaceships, [(i, j+1) for i, j in enumerate(dp[(1 << m) - 1])]

