from collections import deque

def reverse_graph(g):
    rv_graph = {}
    for u, v in g:
        if u not in rv_graph:
            rv_graph[u] = []
        if v not in rv_graph:
            rv_graph[v] = []
        rv_graph[v].append(u)
    return rv_graph

def cycle_counts(g, rv_graph, degrees):
    visited = [False] * (len(g) + 1)
    cycle_count = 0
    cycle_edges = set()

    for u in range(1, len(g) + 1):
        if u not in visited:
            temp_visited = visited[:]
            temp_edges = cycle_edges[:]
            temp_degrees = degrees[:]

            cycle_edges.clear()
            cycle_degrees = {}
            stack = deque([u])
            visited[u] = True

            while stack:
                u = stack[-1]
                cycle_degrees[u] = len(stack)
                ok = False

                for v in rv_graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
                        ok = True
                        break

                if not ok:
                    stack.pop()
                    cycle_edges.add(u)

            cycle_count += 1
            for e in cycle_edges:
                temp_degrees[e - 1] -= 1
                if degrees[e - 1] - temp_degrees[e - 1] == 1:
                    cycle_count -= 1
                    cycle_edges.remove(e)
                    break

            for e, d in cycle_degrees.items():
                if d >= cycle_degrees[u] + 2:
                    cycle_count += 1
                    cycle_edges.add(e)

    return cycle_count

