from collections import Counter

def calc(depths, valid_strs):
    dp = {depth: 0 for depth in depths}
    dp[0] = 1
    for s in valid_strs:
        cur_dp = dp.copy()
        for depth in sorted(dp.keys(), reverse=True):
            if depth == 0:
                continue
            for val in '()':
                new_size = depth - len(s) + depths[val]
                new_dp = cur_dp[depth] * (depth + 1) * dp[new_size]
                cur_dp[new_size] += new_dp
        dp = cur_dp
    return dp[0]

def main():
    n = input()
    depths = Counter(n.count('('), n.count(')')) 
    valid_strs = [(len(s.strip()), s) for s in n.replace('?', '')]
    depth_sum = calc(list(depths.values()), [s for s, d in valid_strs])
    mod = 998244353
    print((depth_sum * 2) % mod)

