import sys

def count_perfect_sequences(n, M):
    MOD = 10**9 + 7
    dp = [1] * (n + 1)

    for r in range(2, n + 1):
        for k in range(r, n + 1):
            dp[k] = (dp[k] + ((k - r + 1) * dp[r]) - dp[k - r] + dp[k] - 1 + MOD) % MOD
            for s in range(r, 10**3 + 1):
                if k - s > 0:
                    dp[k] = dp[k] - (dp[k - s]) % MOD

    return dp[-1]

