    num1 = binary_to_num(current_path_bits[0])
    num2 = binary_to_num(current_path_bits[1])
    difference_bits = sum(bin(num1 ^ num2).count('1') % 2 != k for k in range(2))

    if difference_bits % 2 != minimize_two_distinct_integers(current_path_bits, anchor_points):
        return None

    path_start_bits = current_path_bits[:2]
    for i in range(2, len(set(current_path_bits))):
