        while set(current_path_bits[start:]).issubset(set(current_path_bits[i])):
            if start <= start % 2:
                anchor_points.append(path_start_bits[0])
                path_start_bits = current_path_bits[start:]
            elif start > start % 2:
                anchor_points.append(path_start_bits[1])
                path_start_bits = current_path_bits[start:]
            start -= 1

    return anchor_points

