            x = 1
        if x > 0 and r + x - 1 + N - (r + x) < N:
            x = r + x - 1
        if y > 0 and r + y - 1 + N - (r + y) < N:
            y = r + y - 1
        satisfaction.append(satisfaction[-1] + heights[(x - 1) % N] if heights[(x - 1) % N] > last else last)
        if r + y - x < N:
            r = r + y - x
        else:
            r, x = r + y - x - N, x + y - N
        if r <= 1:
            break

    return satisfaction[-1]

