import sys

def find_parent_or_self(u, parents):
    """Returns the parent of vertex 'u' or 'u' itself."""
    if parents[u] == u:
        return u
    return find_parent_or_self(parents[u], parents)

def join(u, v, edges, graph):
    """Connects vertices 'u' and 'v' sharing at most one edge in common."""
    pu = find_parent_or_self(u, graph)
    pv = find_parent_or_self(v, graph)
    graph[pu] = pv

def remove(u, v, edges, graph):
    """Removes the connection between vertices 'u' and 'v'."""
    pu = find_parent_or_self(u, graph)
    pv = find_parent_or_self(v, graph)
    graph[pu] = graph[pv] = -1

def get_disconnected_edges(edges, graph):
    """Identifies edges that do not connect any two connected vertices."""
    unarities = [False for _ in range(len(edges))]

    for i in range(len(edges)):
        for j in range(i + 1, len(edges)):
            if graph[find_parent_or_self(edges[i][0], graph)] == graph[find_parent_or_self(edges[j][0], graph)]:
                unarities[j] = True
                break

    for i in range(len(edges)):
        if unarities[i] == False:
            yield edges[i]

def main():
    n, m = map(int, input().split())
    edges = [list(map(int, input().split())) for _ in range(m)]

    graph = {}
    connected_edges = set()
    for i in range(m):
        u, v = edges[i]
        join(u, v, edges, graph)
        connected_edges.add((min(u, v), max(u, v)))

    disconnected_edges = list(get_disconnected_edges(edges, graph))
    print(len(disconnected_edges))
    for e in disconnected_edges:
        print(*e)

if __name__ == '__main__':
    main()
