from math import comb

# Computing n mod m pow 998244353 and comb(a, b) mod m using Fermat's Little Theorem for large numbers
def mod_power(x, n, mod):
    result = 1
    while n > 0:
        if n % 2 == 1:
            result = (result * x) % mod
        x = x * x % mod
        n = n >> 1
    return result

def stirling(y, n, mod=998244353):
    result = [[1, 0], [1, 1]]
    for i in range(2, n + 1):
        result += [[result[-1][0] - mod_power(result[-1][1], y, mod) * result[-2][0], result[-1][1] - mod_power(result[-1][1], y, mod) * result[-2][1]]]
    return result[-1]

def find_sequence_type(n: int, m: int) -> int:
    if n == 1:
        return 1
    if n % 2 == 0:
        return 0
    return 1

def count_sequences(n: int, M: int) -> int:
    if n == 1:
        return 1 if M == 2 else 0
    M_wrapper = m = pow(m, 0x0F, 998244353) ^ (998244353 - 2)
    return (count_sequences(n - 1, m) + (M - 2) * count_sequences(n - 1, 2) + pow(comb(n // 2, n // 2 + 1, 998244353), mod_power(M, m, 998244353), 998244353)) % M_wrapper

