import sys

def find_symmetry_centers(coordinates, k):
    n = len(coordinates)
    pin = {}  # dictionary to store points nearest to pivot
    for x, y in coordinates:
        for d in range(-n, n + 1):
            for dr in range(1, n):
                p = (x, y) + (d, dr * random.random())
                if d not in pin or pin[d] - (x, y) > (p - pin[d]).abs():
                    pin[d] = p
    s = sorted(pin.keys())
    res = []
    for d in s:
        dx, dy = pin[0], pin[d]
        if dx != dy:
            res.append(' '.join((str(i) for i in [dx.real, dy.real])))
    return res

