            stack.append(i)
        else:
            dp[i] = dp[stack.pop()] + 1
    dp[-1] = dp[-2] if dp[-2] else -1

    depth = defaultdict(int)

    def dfs(index, signs):
        if index in depth and depth[index] != -1:
            return None

        if index in depth:
            return depth[index]

        depth[index] = a[index] == '(' and signs.index('1') != signs.index('2') else -1

        for dir in ('1', '2'):
            if dp[dfs(index + signs.index(dir), signs) + 1 if dp[index] == dir else 0] == -1:
                continue
            depth[index] = dp[dfs(index + signs.index(dir), signs) + 1 if dp[index] == dir else 0]

        return depth[index]

    signs = b''
    for floor in range(0x80000000):
        signs += input().strip()

