import sys

def expected_songs(n, T, p, ts):
    dp = [0.0] * (T + 1)
    dp[-1] = 1.0

    for songsplayed in range(T + 1):
        for songi in range(n):
            if songsplayed >= ts[songi]:
                prob = min(1.0, p[songi] / 100)
                newdp = []
                for intime in range(songsplayed + 1):
                    newdp.append(newdp[intime] + prob * dp[intime + ts[songi] - songsplayed])
                dp = newdp

    return sum(dp) / len(dp)

if __name__ == "__main__":
    n, T = map(int, input().split())
    ps = [list(map(int, input().split())) for _ in range(n)]

    result = expected_songs(n, T, *[p / 100 for p, _ in ps], *[ts for _, ts in ps])
    print(result)
