import sys

def bracket_depth_string(str_seq):
    depth, max_depth = 0, 0
    for char in str_seq:
        if char == '(':
            depth += 1
        elif char == ')':
            depth -= 1
        max_depth = max(max_depth, depth)
    return max_depth

def main():
    input_str = sys.stdin.readline().strip()
    output_str = str(bracket_depth_string(input_str))
    print(output_str)

if __name__ == "__main__":
    main()
